alter table public.prompts
  add column if not exists source_dataset text,
  add column if not exists source_record_id text,
  add column if not exists adaptation_type text;

insert into public.prompts (
  id, version, prompt_type, language, language_sequence, original_text,
  normalized_text, english_translation, response_seconds, safe_speech, enabled,
  source_dataset, source_record_id, adaptation_type
) values
('SAFE-HA-001',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Fulani sun zama annoba cikin mutane, kuma ba sa son zaman lafiya a Najeriya.',lower('Fulani sun zama annoba cikin mutane, kuma ba sa son zaman lafiya a Najeriya.'),null,null,true,true,'afrihate/afrihate','train_hausa_01744','sanitized extract'),
('SAFE-HA-002',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Ku Fulani ''yan ta''adda ne, kuma ya kamata kowa ya guje ku.',lower('Ku Fulani ''yan ta''adda ne, kuma ya kamata kowa ya guje ku.'),null,null,true,true,'afrihate/afrihate','train_hausa_03130','sanitized extract'),
('SAFE-HA-003',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Fulani ba mutanen zama da su ba ne, domin ba su da kirki.',lower('Fulani ba mutanen zama da su ba ne, domin ba su da kirki.'),null,null,true,true,'afrihate/afrihate','test_hausa_00254','sanitized extract'),
('SAFE-HA-004',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Duk inda aka ga Fulani, mutane su yi taka-tsantsan domin sun zama abin tsoro.',lower('Duk inda aka ga Fulani, mutane su yi taka-tsantsan domin sun zama abin tsoro.'),null,null,true,true,'afrihate/afrihate','dev_hausa_00097','sanitized extract'),
('SAFE-HA-005',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Fulani ''yan wahala ne, ba su san zaman lafiya a Najeriya ba.',lower('Fulani ''yan wahala ne, ba su san zaman lafiya a Najeriya ba.'),null,null,true,true,'afrihate/afrihate','dev_hausa_00893','sanitized extract'),
('SAFE-HA-006',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Kafurai mutane ne marasa mutunci, kuma ba za a amince da su ba.',lower('Kafurai mutane ne marasa mutunci, kuma ba za a amince da su ba.'),null,null,true,true,'afrihate/afrihate','train_hausa_02413','research adaptation'),
('SAFE-HA-007',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Mutanen kudu ba su da amfani, kuma ba sa cancanci a saurare su.',lower('Mutanen kudu ba su da amfani, kuma ba sa cancanci a saurare su.'),null,null,true,true,'afrihate/afrihate','test_hausa_00332','research adaptation'),
('SAFE-HA-008',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Mutane irin ku suna lalata zaman lafiya, don haka ba a son ku a nan.',lower('Mutane irin ku suna lalata zaman lafiya, don haka ba a son ku a nan.'),null,null,true,true,'afrihate/afrihate','train_hausa_02183','research adaptation'),
('SAFE-HA-009',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Wannan ƙabila cike take da masu laifi, kuma babu nagarta a cikinsu.',lower('Wannan ƙabila cike take da masu laifi, kuma babu nagarta a cikinsu.'),null,null,true,true,'afrihate/afrihate','train_hausa_03310','research adaptation'),
('SAFE-HA-010',1,'NaijaSafeSpeech','Hausa',array['Hausa']::text[],'Ba za mu yarda da mutanenku ba, domin kuna kawo tsoro da rikici ko''ina.',lower('Ba za mu yarda da mutanenku ba, domin kuna kawo tsoro da rikici ko''ina.'),null,null,true,true,'afrihate/afrihate','train_hausa_00105','research adaptation'),
('SAFE-IG-001',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Ndị ugwu na ndị ofe mmanụ bụ nnukwu nsogbu obodo a nwere.',lower('Ndị ugwu na ndị ofe mmanụ bụ nnukwu nsogbu obodo a nwere.'),null,null,true,true,'afrihate/afrihate','train_igbo_01772','sanitized extract'),
('SAFE-IG-002',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Ndị ofe mmanụ enweghị uche mmadụ, ha anaghịkwa eme ihe ọma.',lower('Ndị ofe mmanụ enweghị uche mmadụ, ha anaghịkwa eme ihe ọma.'),null,null,true,true,'afrihate/afrihate','train_igbo_02031','sanitized extract'),
('SAFE-IG-003',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Ndị ofe mmanụ bụ ndị jọgburu onwe ha, e kwesịghị ịtụkwasị ha obi.',lower('Ndị ofe mmanụ bụ ndị jọgburu onwe ha, e kwesịghị ịtụkwasị ha obi.'),null,null,true,true,'afrihate/afrihate','test_igbo_00106','research adaptation'),
('SAFE-IG-004',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Ndị ugwu anaghị aba uru n''obodo a, ha na-eweta naanị nsogbu.',lower('Ndị ugwu anaghị aba uru n''obodo a, ha na-eweta naanị nsogbu.'),null,null,true,true,'afrihate/afrihate','train_igbo_00948','research adaptation'),
('SAFE-IG-005',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Hapụ onye ahụ, ị ma na ọ bụ onye ofe mmanụ na-enweghị isi.',lower('Hapụ onye ahụ, ị ma na ọ bụ onye ofe mmanụ na-enweghị isi.'),null,null,true,true,'afrihate/afrihate','dev_igbo_00297','sanitized extract'),
('SAFE-IG-006',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Ụdị mmadụ unu bụ ihe ihere nye obodo, anyị achọghị ka unu bụrụ akụkụ ya.',lower('Ụdị mmadụ unu bụ ihe ihere nye obodo, anyị achọghị ka unu bụrụ akụkụ ya.'),null,null,true,true,'afrihate/afrihate','train_igbo_00442','research adaptation'),
('SAFE-IG-007',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Ndị dị ka unu anaghị enwe uru ọ bụla, unu na-eme ka ndụ ndị ọzọ sie ike.',lower('Ndị dị ka unu anaghị enwe uru ọ bụla, unu na-eme ka ndụ ndị ọzọ sie ike.'),null,null,true,true,'afrihate/afrihate','train_igbo_00612','research adaptation'),
('SAFE-IG-008',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'A gaghị anabata ndị nwere omume unu ebe a n''ihi na unu na-emebi udo.',lower('A gaghị anabata ndị nwere omume unu ebe a n''ihi na unu na-emebi udo.'),null,null,true,true,'afrihate/afrihate','train_igbo_00293','research adaptation'),
('SAFE-IG-009',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Ndị obodo ahụ nwere ọnụ ọjọọ, ha enweghịkwa nkwanye ùgwù.',lower('Ndị obodo ahụ nwere ọnụ ọjọọ, ha enweghịkwa nkwanye ùgwù.'),null,null,true,true,'afrihate/afrihate','train_igbo_02040','research adaptation'),
('SAFE-IG-010',1,'NaijaSafeSpeech','Igbo',array['Igbo']::text[],'Ndị otu a niile bụ ndị aghụghọ, ọ dịghị onye kwesịrị ikwere ha.',lower('Ndị otu a niile bụ ndị aghụghọ, ọ dịghị onye kwesịrị ikwere ha.'),null,null,true,true,'afrihate/afrihate','train_igbo_02502','research adaptation'),
('SAFE-YO-001',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Àwọn ènìyàn yìí jẹ́ ẹranko, ìwà rere kankan kò sí nínú wọn.',lower('Àwọn ènìyàn yìí jẹ́ ẹranko, ìwà rere kankan kò sí nínú wọn.'),null,null,true,true,'afrihate/afrihate','train_yoruba_01234','research adaptation'),
('SAFE-YO-002',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Ọmọ àlè ni ẹni yẹn, kò sì yẹ kó pe ara rẹ̀ ní ọmọ Yorùbá.',lower('Ọmọ àlè ni ẹni yẹn, kò sì yẹ kó pe ara rẹ̀ ní ọmọ Yorùbá.'),null,null,true,true,'afrihate/afrihate','train_yoruba_01616','sanitized extract'),
('SAFE-YO-003',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Àwọn ènìyàn wọ̀nyí jẹ́ òmùgọ̀, wọn kì í lè ṣe ohun tó tọ́.',lower('Àwọn ènìyàn wọ̀nyí jẹ́ òmùgọ̀, wọn kì í lè ṣe ohun tó tọ́.'),null,null,true,true,'afrihate/afrihate','train_yoruba_00791','research adaptation'),
('SAFE-YO-004',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Àwọn ènìyàn bí ẹ̀yin kì í ṣe ohun tí àwùjọ fẹ́, ẹ ń fa ìṣòro sí gbogbo ènìyàn.',lower('Àwọn ènìyàn bí ẹ̀yin kì í ṣe ohun tí àwùjọ fẹ́, ẹ ń fa ìṣòro sí gbogbo ènìyàn.'),null,null,true,true,'afrihate/afrihate','train_yoruba_02237','research adaptation'),
('SAFE-YO-005',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Ìwà yín jẹ́ àbùkù, àwọn bí ẹ̀yin kò yẹ kí wọ́n ní ipa nínú àwùjọ.',lower('Ìwà yín jẹ́ àbùkù, àwọn bí ẹ̀yin kò yẹ kí wọ́n ní ipa nínú àwùjọ.'),null,null,true,true,'afrihate/afrihate','train_yoruba_03080','research adaptation'),
('SAFE-YO-006',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Ẹ̀gbẹ́ yín ló ń ba ìdàgbàsókè wa jẹ́, kò sí ohun rere tí ẹ mú wá.',lower('Ẹ̀gbẹ́ yín ló ń ba ìdàgbàsókè wa jẹ́, kò sí ohun rere tí ẹ mú wá.'),null,null,true,true,'afrihate/afrihate','test_yoruba_00408','research adaptation'),
('SAFE-YO-007',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Àwọn ará àríwá jẹ́ aláìgbọ́ràn, wọn kò sì yẹ kí a gbẹ́kẹ̀ lé wọn.',lower('Àwọn ará àríwá jẹ́ aláìgbọ́ràn, wọn kò sì yẹ kí a gbẹ́kẹ̀ lé wọn.'),null,null,true,true,'afrihate/afrihate','train_yoruba_01006','research adaptation'),
('SAFE-YO-008',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Ojú àwọn ènìyàn yẹn kò kúrò nínú ìwà búburú àti ìtanilẹ́yìn.',lower('Ojú àwọn ènìyàn yẹn kò kúrò nínú ìwà búburú àti ìtanilẹ́yìn.'),null,null,true,true,'afrihate/afrihate','dev_yoruba_00460','research adaptation'),
('SAFE-YO-009',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Ẹ̀yin ọmọ ẹ̀yà yẹn jẹ́ ẹlẹ́rù, ẹnu lásán lẹ ní láìsí ìgboyà.',lower('Ẹ̀yin ọmọ ẹ̀yà yẹn jẹ́ ẹlẹ́rù, ẹnu lásán lẹ ní láìsí ìgboyà.'),null,null,true,true,'afrihate/afrihate','train_yoruba_01980','research adaptation'),
('SAFE-YO-010',1,'NaijaSafeSpeech','Yorùbá',array['Yorùbá']::text[],'Ẹ̀sìn àwọn ènìyàn wọ̀nyí ti ba àṣà wa jẹ́, wọn kò yẹ kí wọ́n wà láàárín wa.',lower('Ẹ̀sìn àwọn ènìyàn wọ̀nyí ti ba àṣà wa jẹ́, wọn kò yẹ kí wọ́n wà láàárín wa.'),null,null,true,true,'afrihate/afrihate','train_yoruba_00257','sanitized extract'),
('SAFE-PCM-001',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'Those people no be real citizens, na fake patriotic people dem be.',lower('Those people no be real citizens, na fake patriotic people dem be.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00005','sanitized extract'),
('SAFE-PCM-002',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'Dem make us believe say Africans barbaric, but those people worse pass animals.',lower('Dem make us believe say Africans barbaric, but those people worse pass animals.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00006','sanitized extract'),
('SAFE-PCM-003',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'Make all of una comot, una be hypocrites wey no fit ever talk truth.',lower('Make all of una comot, una be hypocrites wey no fit ever talk truth.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00023','sanitized extract'),
('SAFE-PCM-004',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'People from that religion dey cause every problem, dem no get respect for anybody.',lower('People from that religion dey cause every problem, dem no get respect for anybody.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00030','research adaptation'),
('SAFE-PCM-005',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'Northerners dey kill, destroy property and cause trouble anywhere dem go.',lower('Northerners dey kill, destroy property and cause trouble anywhere dem go.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00052','sanitized extract'),
('SAFE-PCM-006',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'I no fit trust any Fulani person because all of dem dey support violence.',lower('I no fit trust any Fulani person because all of dem dey support violence.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00056','research adaptation'),
('SAFE-PCM-007',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'Yoruba men no good for anything, dem just dey make noise everywhere.',lower('Yoruba men no good for anything, dem just dey make noise everywhere.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00061','research adaptation'),
('SAFE-PCM-008',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'Those northerners stupid, dem go collect anything but dem no get sense to choose well.',lower('Those northerners stupid, dem go collect anything but dem no get sense to choose well.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00072','research adaptation'),
('SAFE-PCM-009',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'People like una make bad leaders remain in power, una no fit think for unaself.',lower('People like una make bad leaders remain in power, una no fit think for unaself.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00086','research adaptation'),
('SAFE-PCM-010',1,'NaijaSafeSpeech','Nigerian Pidgin',array['Nigerian Pidgin']::text[],'Girls from that place primitive, and dem no suppose mix with civilized people.',lower('Girls from that place primitive, and dem no suppose mix with civilized people.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00136','research adaptation'),
('SAFE-EN-001',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'People from that ethnic group are criminals, and nobody should trust them.',lower('People from that ethnic group are criminals, and nobody should trust them.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00075','research adaptation'),
('SAFE-EN-002',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'That community produces only violent people who destroy every place they enter.',lower('That community produces only violent people who destroy every place they enter.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00052','research adaptation'),
('SAFE-EN-003',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'Members of that religion are hypocrites who are too afraid to tell the truth.',lower('Members of that religion are hypocrites who are too afraid to tell the truth.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00023','research adaptation'),
('SAFE-EN-004',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'Those people are the real barbarians, and they behave worse than animals.',lower('Those people are the real barbarians, and they behave worse than animals.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00006','research adaptation'),
('SAFE-EN-005',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'No person from that tribe can be trusted with leadership in Nigeria.',lower('No person from that tribe can be trusted with leadership in Nigeria.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00056','research adaptation'),
('SAFE-EN-006',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'People from the north are foolish and will never make a sensible political choice.',lower('People from the north are foolish and will never make a sensible political choice.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00072','research adaptation'),
('SAFE-EN-007',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'Women from that state are primitive and do not belong among civilized people.',lower('Women from that state are primitive and do not belong among civilized people.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00136','research adaptation'),
('SAFE-EN-008',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'Your ethnic group is cowardly, loud, and incapable of standing for anything important.',lower('Your ethnic group is cowardly, loud, and incapable of standing for anything important.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00145','research adaptation'),
('SAFE-EN-009',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'People of that sexual orientation are disgusting and should not be accepted here.',lower('People of that sexual orientation are disgusting and should not be accepted here.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00132','research adaptation'),
('SAFE-EN-010',1,'NaijaSafeSpeech','Nigerian English',array['Nigerian English']::text[],'Women are all dishonest and useless, so their opinions should never be taken seriously.',lower('Women are all dishonest and useless, so their opinions should never be taken seriously.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00149','research adaptation'),
('SAFE-CS-001',1,'NaijaSafeSpeech','Igbo + Nigerian English',array['Igbo','Nigerian English']::text[],'Ndị ugwu are the major problem in this country, and nobody should trust them.',lower('Ndị ugwu are the major problem in this country, and nobody should trust them.'),null,null,true,true,'afrihate/afrihate','train_igbo_01772','research adaptation'),
('SAFE-CS-002',1,'NaijaSafeSpeech','Igbo + Nigerian English',array['Igbo','Nigerian English']::text[],'Onye ofe mmanụ like you is not welcome here because your people cause trouble.',lower('Onye ofe mmanụ like you is not welcome here because your people cause trouble.'),null,null,true,true,'afrihate/afrihate','train_igbo_00442','research adaptation'),
('SAFE-CS-003',1,'NaijaSafeSpeech','Yorùbá + Nigerian English',array['Yorùbá','Nigerian English']::text[],'Ẹ̀yin ọmọ ẹ̀yà yẹn are cowards, you only know how to make noise.',lower('Ẹ̀yin ọmọ ẹ̀yà yẹn are cowards, you only know how to make noise.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00145','research adaptation'),
('SAFE-CS-004',1,'NaijaSafeSpeech','Yorùbá + Nigerian English',array['Yorùbá','Nigerian English']::text[],'Ọmọ àlè ni ẹ, and people like you bring shame to the whole community.',lower('Ọmọ àlè ni ẹ, and people like you bring shame to the whole community.'),null,null,true,true,'afrihate/afrihate','train_yoruba_01616','research adaptation'),
('SAFE-CS-005',1,'NaijaSafeSpeech','Hausa + Nigerian English',array['Hausa','Nigerian English']::text[],'Ku Fulani ''yan ta''adda ne, and nobody should allow your people to lead.',lower('Ku Fulani ''yan ta''adda ne, and nobody should allow your people to lead.'),null,null,true,true,'afrihate/afrihate','train_hausa_03130','research adaptation'),
('SAFE-CS-006',1,'NaijaSafeSpeech','Hausa + Nigerian English',array['Hausa','Nigerian English']::text[],'Mutanen kudu ba su da amfani, they contribute nothing good to this country.',lower('Mutanen kudu ba su da amfani, they contribute nothing good to this country.'),null,null,true,true,'afrihate/afrihate','test_hausa_00332','research adaptation'),
('SAFE-CS-007',1,'NaijaSafeSpeech','Nigerian English + Nigerian Pidgin',array['Nigerian English','Nigerian Pidgin']::text[],'Those people are criminals, na only trouble dem dey carry come.',lower('Those people are criminals, na only trouble dem dey carry come.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00075','research adaptation'),
('SAFE-CS-008',1,'NaijaSafeSpeech','Nigerian English + Nigerian Pidgin',array['Nigerian English','Nigerian Pidgin']::text[],'Your community cannot be trusted, una dey support violence every time.',lower('Your community cannot be trusted, una dey support violence every time.'),null,null,true,true,'afrihate/afrihate','train_nigerian_pidgin_00082','research adaptation'),
('SAFE-CS-009',1,'NaijaSafeSpeech','Igbo + Nigerian English + Nigerian Pidgin',array['Igbo','Nigerian English','Nigerian Pidgin']::text[],'Ndị dị ka unu are not welcome here, na problem una dey bring everywhere.',lower('Ndị dị ka unu are not welcome here, na problem una dey bring everywhere.'),null,null,true,true,'afrihate/afrihate','train_igbo_00293','research adaptation'),
('SAFE-CS-010',1,'NaijaSafeSpeech','Yorùbá + Nigerian English + Nigerian Pidgin',array['Yorùbá','Nigerian English','Nigerian Pidgin']::text[],'Àwọn ènìyàn yẹn are useless, na only confusion dem dey cause for society.',lower('Àwọn ènìyàn yẹn are useless, na only confusion dem dey cause for society.'),null,null,true,true,'afrihate/afrihate','train_yoruba_02237','research adaptation'),
('SAFE-CS-011',1,'NaijaSafeSpeech','Hausa + Nigerian English + Nigerian Pidgin',array['Hausa','Nigerian English','Nigerian Pidgin']::text[],'Fulani ba mutanen zama da su ba, nobody fit trust dem for this country.',lower('Fulani ba mutanen zama da su ba, nobody fit trust dem for this country.'),null,null,true,true,'afrihate/afrihate','test_hausa_00254','research adaptation'),
('SAFE-CS-012',1,'NaijaSafeSpeech','Igbo + Nigerian English + Nigerian Pidgin',array['Igbo','Nigerian English','Nigerian Pidgin']::text[],'Ndị otu ahụ have nothing positive to offer, na division dem dey create.',lower('Ndị otu ahụ have nothing positive to offer, na division dem dey create.'),null,null,true,true,'afrihate/afrihate','train_igbo_02502','research adaptation')
on conflict (id) do update set
